changeSet.sql:
ALTER TABLE tariff_rate
    ADD CONSTRAINT ck_tariff_rate_window
    CHECK (valid_to IS NULL OR valid_to > valid_from);

ALTER TABLE tariff_rate
    ADD CONSTRAINT ck_tariff_rate_prices
    CHECK (purchase_price_per_kwh >= 0 AND (export_price_per_kwh IS NULL OR export_price_per_kwh >= 0));

ALTER TABLE loss_assessment
    ADD CONSTRAINT ck_loss_assessment_non_negative
    CHECK (total_loss_wh >= 0);

ALTER TABLE loss_cause_estimate
    ADD CONSTRAINT ck_loss_cause_non_negative
    CHECK (estimated_wh >= 0);

ALTER TABLE economic_assessment
    ADD CONSTRAINT ck_economic_assessment_non_negative
    CHECK (estimated_loss_amount >= 0);
